import threading
from concurrent.futures import Future, ThreadPoolExecutor

import pytest


class Bad(Exception):
    def __init__(self, n: int) -> None:
        self.n = n


def check(x: int) -> int:
    if x % 2 == 1:
        raise Bad(x)
    return x


def all_even(xs: list[int]) -> list[int]:
    """Check every element of xs in parallel using a thread pool.

    Returns the checked values in input order. If any element is bad,
    raises the Bad of the lowest-index bad element, regardless of which
    thread finishes first.
    """
    workers = max(1, min(32, len(xs)))
    with ThreadPoolExecutor(max_workers=workers) as ex:
        futures: list[Future[int]] = [ex.submit(check, x) for x in xs]
        # Collect results in index order, so the first exception raised is
        # that of the lowest-index bad element, whatever the finish order.
        return [f.result() for f in futures]


def test_all_even_ok() -> None:
    assert all_even([2, 4, 6, 0, -8]) == [2, 4, 6, 0, -8]


def test_all_even_empty() -> None:
    assert all_even([]) == []


def test_all_even_preserves_order() -> None:
    xs = list(range(0, 200, 2))
    assert all_even(xs) == xs


def test_single_bad() -> None:
    with pytest.raises(Bad) as ei:
        all_even([2, 4, 7, 8])
    assert ei.value.n == 7


def test_lowest_index_bad_wins() -> None:
    # Values chosen so that lowest index is not the smallest/largest value.
    with pytest.raises(Bad) as ei:
        all_even([2, 9, 4, 3, 5])
    assert ei.value.n == 9


def test_lowest_index_wins_even_if_later_finishes_first(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    gate = threading.Event()
    original = check

    def fake_check(x: int) -> int:
        if x == 3:
            # Lowest-index bad element: finishes only after the later bad one.
            gate.wait(timeout=2.0)
            return original(x)
        if x == 5:
            try:
                return original(x)
            finally:
                gate.set()
        return original(x)

    monkeypatch.setitem(globals(), "check", fake_check)
    with pytest.raises(Bad) as ei:
        all_even([3, 4, 5])
    assert ei.value.n == 3


def test_checks_run_in_worker_threads(monkeypatch: pytest.MonkeyPatch) -> None:
    seen: set[int] = set()
    lock = threading.Lock()
    original = check

    def fake_check(x: int) -> int:
        with lock:
            seen.add(threading.get_ident())
        return original(x)

    monkeypatch.setitem(globals(), "check", fake_check)
    assert all_even([2, 4, 6, 8]) == [2, 4, 6, 8]
    assert threading.get_ident() not in seen


def test_every_element_is_checked_despite_bad(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    called: list[int] = []
    lock = threading.Lock()
    original = check

    def fake_check(x: int) -> int:
        with lock:
            called.append(x)
        return original(x)

    monkeypatch.setitem(globals(), "check", fake_check)
    with pytest.raises(Bad) as ei:
        all_even([1, 2, 4, 6])
    assert ei.value.n == 1
    assert sorted(called) == [1, 2, 4, 6]

